n=16
grid=[[7]*n for _ in range(n)]
# Complete each diagonal stroke within the band used in the demo: r+c=12..22.
for d,color in [(10,2),(6,2),(0,2),(-4,4),(-8,4)]:
    for r in range(n):
        c=r+d
        if 0<=c<n and 12<=r+c<=22:
            grid[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in grid))
